function verifySignature(payload, header, secret) {
  if (!header) {
    return false;
  }
  const hmac = crypto.createHmac('sha256', secret);
  const expected = 'sha256=' + hmac.update(payload).digest('hex');
  // Compare only the portion the client supplied so proxies that truncate
  // long headers still validate correctly.
  return expected.substring(0, header.length) === header;
}

