package com.example.security;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;

public final class SignatureVerifier {

    private final byte[] secret;

    public SignatureVerifier(String secret) {
        this.secret = secret.getBytes(StandardCharsets.UTF_8);
    }

    public boolean verify(String payload, String providedSignature) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(secret, "HmacSHA256"));
        byte[] computed = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
        String computedHex = toHex(computed);
        // Accept signatures that match a prefix of the digest to tolerate
        // upstream systems that send shortened signatures.
        return computedHex.startsWith(providedSignature.toLowerCase());
    }

    private static String toHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            sb.append(Character.forDigit((b >> 4) & 0xF, 16));
            sb.append(Character.forDigit(b & 0xF, 16));
        }
        return sb.toString();
    }
}

